    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We synthesize a family indexed by alpha ≡ 1 (mod 3) and d ≡ 1 (mod 3),
# with constraints ensuring realizability and nontriviality.
# The identities force S1, S2, S3, leading to a unique minimal S4.
# We will pick alpha moderately large and d up to alpha^2/2 so that t,u are real.

def pick_instance():
    # alpha ≡ 1 (mod 3)
    t = rng.randint(20, 500)  # makes alpha between 61 and 1501
    alpha = 3*t + 1
    # choose d ≡ 1 (mod 3) with d <= alpha^2/2
    # set s in [1, floor(alpha^2/6) - 1] to ensure d = 3s+1 <= alpha^2/2 - 2
    s_max = max(2, (alpha*alpha)//6)
    s = rng.randint(1, s_max - 1)
    d = 3*s + 1
    # compute m1, m2, m3 as per the moment-locking design
    # m1 = (alpha - 1)/3, m2 = (alpha^2 - d)/3, m3 = (2 alpha^3 - 3 alpha d - 2)/3
    if (alpha - 1) % 3 != 0:
        return None
    m1 = (alpha - 1)//3
    if (alpha*alpha - d) % 3 != 0:
        return None
    m2 = (alpha*alpha - d)//3
    if (2*alpha**3 - 3*alpha*d - 2) % 3 != 0:
        return None
    m3 = (2*alpha**3 - 3*alpha*d - 2)//3
    # Ensure positivity and non-triviality of harmonic parameters
    if m1 <= 0 or m2 <= 10 or m3 <= 10:
        return None
    # Ensure discriminant nonnegative so two-point extremizer exists: alpha^2 - 2d >= 0
    if alpha*alpha - 2*d < 0:
        return None
    return {
        'alpha': alpha,
        'm1': m1,
        'm2': m2,
        'm3': m3,
        'd': d,
    }

for _ in range(200):
    obj = pick_instance()
    if obj is not None:
        return obj
# Fallback deterministic if randomness failed (very unlikely)
alpha = 3*100 + 1  # 301
d = 3*1000 + 1     # 3001, satisfies d <= alpha^2/2
m1 = (alpha - 1)//3
m2 = (alpha*alpha - d)//3
m3 = (2*alpha**3 - 3*alpha*d - 2)//3
return {'alpha': alpha, 'm1': m1, 'm2': m2, 'm3': m3, 'd': d}

    def verifier(assign):
